"""Threshold sensitivity of two fixed inspection orders in the EvalPerf primary comparison."""
from fractions import Fraction
from itertools import accumulate, product, permutations
from math import prod
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
import base64,hashlib,json

def profile(counts,d):
    m=len(counts);t=2*m
    den_block=d*(d-1)
    denom=den_block**m
    diff=[0]*(t+2)
    weights=[1]
    def add_prefix(ws,k,mult):
        # An unfinished decision has threshold in [h+1,h+t-k].
        for h,x in enumerate(ws):
            diff[h+1]+=x*mult
            diff[h+t-k+1]-=x*mult
    for i,c in enumerate(counts):
        q=d-c
        suffix=den_block**(m-i-1)
        add_prefix(weights,2*i,suffix*den_block)
        odd=[0]*(len(weights)+1)
        nxt=[0]*(len(weights)+2)
        for h,x in enumerate(weights):
            odd[h]+=q*x
            odd[h+1]+=c*x
            nxt[h]+=q*(q-1)*x
            nxt[h+1]+=2*q*c*x
            nxt[h+2]+=c*(c-1)*x
        add_prefix(odd,2*i+1,suffix*(d-1))
        weights=nxt
    costs=[Fraction(v,denom) for v in list(accumulate(diff))[1:t+1]]
    if sum(costs)!=t*(t+1)//2 or sum(weights)!=denom:raise ValueError('sum rule')
    return costs,weights

def shuffled(weights):
    t=len(weights)-1
    den=sum(weights)
    # Prefix sums of w/(h+1) and w/(T-h+1).
    pos=[Fraction(0),*accumulate(Fraction(x,h+1) for h,x in enumerate(weights))]
    neg=[Fraction(0),*accumulate(Fraction(x,t-h+1) for h,x in enumerate(weights))]
    return [(t+1)*(r*(pos[-1]-pos[r])+(t-r+1)*neg[r])/den for r in range(1,t+1)]

def tiny():
    tests=0
    for counts in product(range(4),repeat=2):
        p,w=profile(counts,3)
        totals=[0]*4
        for a,b in product(permutations(range(3),2),repeat=2):
            bits=[v<c for pair,c in zip([a,b],counts) for v in pair]
            times=[]
            for r in range(1,5):
                hit=0
                for k,s in enumerate(bits,1):
                    hit+=s
                    if hit==r or k-hit==5-r:break
                times.append(k);totals[r-1]+=k
            if sorted(times)!=[1,2,3,4]:raise ValueError('pathwise permutation')
        if [Fraction(x,36) for x in totals]!=p:raise ValueError('brute')
        tests+=1
    return tests

def runs(deltas):
    out=[]
    for r,delta in enumerate(deltas,1):
        sign=(delta>0)-(delta<0)
        if out and out[-1][2]==sign:out[-1][1]=r
        else:out.append([r,r,sign])
    return out

def main():
    data=json.loads(base64.b64decode(''))
    target=data['counts']
    easy,weights=profile([target[id] for id in data['desc']],100)
    hard,w2=profile([target[id] for id in data['asc']],100)
    rand=shuffled(weights)
    if weights!=w2 or sum(rand)!=sum(easy):raise ValueError('full law changed')
    m=len(target)
    for name,x in [('desc',easy),('asc',hard),('shuffled',rand)]:
        if x[m-1]!=Fraction(data[name+'_at_m']):raise ValueError('prior audit disagrees')
    results={}
    for name,other in [('reverse',hard),('uniform_slots',rand)]:
        diff=[b-a for a,b in zip(easy,other)]
        if sum(diff)!=0:raise ValueError('imbalanced cost differences')
        results[name]=dict(sign_intervals=runs(diff),largest_saving=[diff.index(max(diff))+1,float(max(diff))],
                           largest_penalty=[diff.index(min(diff))+1,float(-min(diff))],savings_exact=[str(x) for x in diff])
    obj=dict(tiny=tiny(),size=2*m,profile=results,source=data['source'],sum_cost=int(sum(easy)))
    out=Path('/content/archive.zip')
    with ZipFile(out,'w',ZIP_DEFLATED) as z:z.writestr('thresholds.json',json.dumps(obj,sort_keys=True))
    print('archive_sha256',hashlib.sha256(out.read_bytes()).hexdigest())
if __name__=='__main__':main()

